const test = require("node:test");
const assert = require("node:assert");

const { startServer, api } = require("./helpers");

test("bulk-add: rejects the WHOLE batch if the cumulative quantity would exceed maxCapacity", async () => {
  const { base, close } = startServer();
  try {
    const wh = await api(base, "POST", "/api/warehouses", {
      name: "Main",
      location: "NYC",
      maxCapacity: 10,
    });
    const whId = wh.json.id;

    const resp = await api(base, "POST", "/api/items/bulk-add", {
      warehouseId: whId,
      items: [
        { sku: "A", name: "Widget A", quantity: 6 },
        { sku: "B", name: "Widget B", quantity: 6 },
      ],
    });
    assert.strictEqual(resp.status, 400);

    const items = await api(base, "GET", `/api/items?warehouseId=${whId}`);
    assert.deepStrictEqual(items.json, []);
  } finally {
    await close();
  }
});

test("bulk-add: succeeds when the batch fits within maxCapacity", async () => {
  const { base, close } = startServer();
  try {
    const wh = await api(base, "POST", "/api/warehouses", {
      name: "Main",
      location: "NYC",
      maxCapacity: 10,
    });
    const whId = wh.json.id;

    const resp = await api(base, "POST", "/api/items/bulk-add", {
      warehouseId: whId,
      items: [
        { sku: "A", name: "Widget A", quantity: 4 },
        { sku: "B", name: "Widget B", quantity: 4 },
      ],
    });
    assert.strictEqual(resp.status, 201);

    const items = await api(base, "GET", `/api/items?warehouseId=${whId}`);
    assert.strictEqual(items.json.length, 2);
  } finally {
    await close();
  }
});

